class Handler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path.split("?")[0] not in ("/", "/index.html"):
            self.send_error(404); return
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(PAGE)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(PAGE)

    def log_message(self, *a):
        pass


def open_browser(url, kiosk=True):
    for exe in ("chromium", "chromium-browser", "google-chrome", "google-chrome-stable"):
        path = shutil.which(exe)
        if path:
            args = [path, "--autoplay-policy=no-user-gesture-required"]
            if kiosk:
                args.append("--kiosk")
            subprocess.Popen(args + [url],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            return True
    return webbrowser.open(url)


def main():
    ap = argparse.ArgumentParser(add_help=True)
    ap.add_argument("--port", type=int, default=8080)
    ap.add_argument("--host", default="127.0.0.1")
    ap.add_argument("--no-browser", action="store_true")
    ap.add_argument("--no-kiosk", action="store_true")
    ap.add_argument("--export", metavar="FILE")
    args = ap.parse_args()

    if args.export:
        with open(args.export, "wb") as f:
            f.write(PAGE)
        print("已导出：%s" % os.path.abspath(args.export))
        return

    socketserver.TCPServer.allow_reuse_address = True
    port = args.port
    for _ in range(20):
        try:
            srv = socketserver.TCPServer((args.host, port), Handler)
            break
        except OSError:
            port += 1
    else:
        print("端口都被占用了，用 --port 指定一个"); sys.exit(1)

    url = "http://localhost:%d/" % port
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    print(url)
    print("麦克风需要在这个地址下才可用。Ctrl+C 退出。")

    if not args.no_browser:
        time.sleep(0.4)
        open_browser(url, kiosk=not args.no_kiosk)

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        srv.shutdown()


if __name__ == "__main__":
    main()
